const requested = $json.season;
const month = $now.month;
const name = month <= 3 ? 'winter' : month <= 6 ? 'spring' : month <= 9 ? 'summer' : 'fall';
const season = requested === undefined || requested === null || requested === ''
  ? `${name}-${$now.year}`
  : String(requested).trim().toLowerCase();
if (!/^(spring|summer|fall|winter)-\d{4}$/.test(season)) {
  throw new Error(`Invalid season: ${season}`);
}
return [{ json: { season } }];

if (typeof $json.stdout !== 'string' || $json.stdout.trim() === '') {
  throw new Error('Discovery command returned no JSON');
}
let payload;
try {
  payload = JSON.parse($json.stdout);
} catch (error) {
  throw new Error(`Discovery command returned invalid JSON: ${error.message}`);
}
if (!/^(spring|summer|fall|winter)-\d{4}$/.test(payload.season ?? '')) {
  throw new Error('Discovery response has an invalid season');
}
if (!Number.isInteger(payload.show_count) || payload.show_count < 1) {
  throw new Error('Discovery response has an invalid show_count');
}
if (!Array.isArray(payload.new_shows) || !Array.isArray(payload.seen_shows)) {
  throw new Error('Discovery response is missing show arrays');
}
if (payload.show_count !== payload.new_shows.length + payload.seen_shows.length) {
  throw new Error('Discovery response show_count does not match its arrays');
}
return [{ json: payload }];
